(() => {
  'use strict';
  const KEY = 'missionChine2026.v1';
  const TENCENT_URL = 'https://docs.qq.com/sheet/DSnBjT2RSUnpYV0J2?tab=000001';
  const fmtEUR = new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0});
  const today = '2026-11-19';
  const uid = () => Math.random().toString(36).slice(2,9);
  const esc = value => String(value ?? '').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const icons = {
    mission:'<svg viewBox="0 0 24 24"><path d="M3 11.5 12 4l9 7.5M5.5 10v9h13v-9M9 19v-5h6v5"/></svg>',
    vision:'<svg viewBox="0 0 24 24"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.5"/></svg>',
    finance:'<svg viewBox="0 0 24 24"><path d="M4 19V9m5 10V5m6 14v-7m5 7V3"/></svg>',
    france:'<svg viewBox="0 0 24 24"><path d="m7 3 10 3 2 11-7 4-7-4L7 3Z"/><path d="m8 10 3 2 5-4"/></svg>',
    sal:'<svg viewBox="0 0 24 24"><path d="M3 17c4-4 7-4 11 0 2 2 4 1 7-1M4 13c2-3 5-5 9-4 3 1 5 3 7 5M12 5V3m5 4 1.5-1.5M7 7 5.5 5.5"/></svg>',
    carnet:'<svg viewBox="0 0 24 24"><path d="M5 4h12a2 2 0 0 1 2 2v14H7a2 2 0 0 1-2-2V4Z"/><path d="M8 4v16m3-12h5m-5 4h5"/></svg>',
    contacts:'<svg viewBox="0 0 24 24"><circle cx="9" cy="8" r="3"/><path d="M3.5 19c.5-4 2.5-6 5.5-6s5 2 5.5 6M16 7h5m-5 4h5m-4 4h4"/></svg>',
    roadmap:'<svg viewBox="0 0 24 24"><path d="M5 3v18M5 6h10l-2.5 3L15 12H5"/></svg>',
    journal:'<svg viewBox="0 0 24 24"><path d="M5 3h14v18H5zM8 7h8m-8 4h8m-8 4h5"/></svg>',
    presentation:'<svg viewBox="0 0 24 24"><path d="M4 4h16v11H4zM8 20l4-5 4 5M2 4h20"/></svg>'
  };
  icons.timeline=icons.roadmap;
  icons.catalogue='<svg viewBox="0 0 24 24"><path d="M4 5h16v14H4zM4 10h16M9 5v14M14 5v14"/></svg>';
  icons.equipe=icons.contacts;
  icons.pilotage='<svg viewBox="0 0 24 24"><path d="M4 19V9m5 10V5m6 14v-7m5 7V3"/><path d="M2 21h20"/></svg>';
  const primaryRoutes = [['mission','Accueil'],['timeline','Timeline'],['catalogue','25 achats'],['equipe','Équipe'],['pilotage','Pilotage']];
  const secondaryRoutes = [['vision','Vision'],['finance','Finances'],['france','Opportunités France'],['sal','Opportunités Sal'],['carnet','Carnet Guangzhou'],['contacts','Contacts'],['roadmap','Roadmap'],['journal','Journal'],['presentation','Présentation']];
  const routes = [...primaryRoutes,...secondaryRoutes];
  const purchaseSlots = Array.from({length:25},(_,i)=>({id:`achat-${String(i+1).padStart(2,'0')}`,slot:i+1,product:'',category:'',quantity:1,status:'À qualifier',note:''}));
  const defaults = {
    meta:{version:'2.2',updatedAt:today,exchangeRate:7.31},
    finance:{envelope:0,travelBudget:0,actualExpenses:0,productCost:0,revenue:0,received:0,repayment:0,remainingDebt:0},
    metrics:{progress:18,prospects:0,buyers:0,orders:0,verifiedSuppliers:0,estimatedMargin:0,received:0,salOpportunities:9},
    france:[
      {id:uid(),product:'DJI Osmo Pocket',category:'Technologie',target:'Créateurs de contenu',interest:0,rmb:0,shipping:0,taxes:0,fees:0,sale:0,commission:0,risk:'Moyen',status:'prix à vérifier',action:'Comparer prix officiel et coût complet',example:true},
      {id:uid(),product:'iPhone',category:'Technologie',target:'Acheteur français',interest:0,rmb:0,shipping:0,taxes:0,fees:0,sale:0,commission:0,risk:'Élevé',status:'demande à tester',action:'Vérifier conformité, garantie et fiscalité',example:true},
      {id:uid(),product:'Accessoires pour créateurs',category:'Accessoires',target:'Créateurs de contenu',interest:0,rmb:0,shipping:0,taxes:0,fees:0,sale:0,commission:0,risk:'Faible',status:'idée',action:'Interroger 5 acheteurs potentiels',example:true},
      {id:uid(),product:'Accessoires automobiles compacts',category:'Automobile',target:'Automobilistes / loueurs',interest:0,rmb:0,shipping:0,taxes:0,fees:0,sale:0,commission:0,risk:'Moyen',status:'idée',action:'Lister besoins précis et normes',example:true},
      {id:uid(),product:'Produits technologiques faciles à transporter',category:'Technologie',target:'À définir',interest:0,rmb:0,shipping:0,taxes:0,fees:0,sale:0,commission:0,risk:'Moyen',status:'demande à tester',action:'Sélectionner 3 produits conformes',example:true}
    ],
    sal:['Vélos électriques','Équipements de loisirs','Équipements d’excursions','Accessoires pour hôtels','Produits pour agences de voyages','Accessoires pour entreprises de location automobile','Équipements d’événements','Solutions d’énergie légère','Activités touristiques hors des grands resorts'].map((name,i)=>({id:uid(),name,need:'À vérifier sur place',partner:'À identifier',investment:0,transport:0,maintenance:0,insurance:0,revenue:0,payback:'À estimer',risks:'Demande, logistique et réglementation à vérifier',action:'Valider le besoin avec 3 interlocuteurs',decision:i===0?'hypothèse prioritaire à valider':'hypothèse à étudier',priority:i===0})),
    catalogue:purchaseSlots,
    carnet:[],contacts:[],journal:[]
  };
  let state = load();
  let current = location.hash.slice(1) || 'mission';
  let presentation = false;
  function migrate(v){
    const legacyExample=(v?.france||[]).find(o=>o.example&&o.product==='DJI Osmo Pocket'&&o.rmb===2999&&o.shipping===45&&o.taxes===95&&o.fees===12&&o.sale===620);
    if(legacyExample)Object.assign(legacyExample,{rmb:0,shipping:0,taxes:0,fees:0,sale:0});
    if(v?.meta)v.meta.version='2.2';
    return v;
  }
  function load(){try{const v=JSON.parse(localStorage.getItem(KEY));return v?merge(defaults,migrate(v)):structuredClone(defaults)}catch{return structuredClone(defaults)}}
  function merge(base,extra){const out=structuredClone(base);Object.keys(extra||{}).forEach(k=>{out[k]=(extra[k]&&typeof extra[k]==='object'&&!Array.isArray(extra[k]))?{...(out[k]||{}),...extra[k]}:extra[k]});return out}
  function save(message='Modifications enregistrées'){state.meta.updatedAt=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(state));document.querySelector('#saveStatus').textContent=message;toast(message)}
  function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2200)}
  function money(v){return fmtEUR.format(Number(v)||0)}
  function rmbDisplay(v){return `${new Intl.NumberFormat('fr-FR').format(Number(v)||0)} RMB — environ ${money((Number(v)||0)/state.meta.exchangeRate)}`}
  function cost(o){return (Number(o.rmb)||0)/state.meta.exchangeRate+(Number(o.shipping)||0)+(Number(o.taxes)||0)+(Number(o.fees)||0)}
  function margin(o){return (Number(o.sale)||0)-cost(o)-(Number(o.commission)||0)}
  function statusTag(text,type=''){return `<span class="tag ${type}">${esc(text)}</span>`}
  function pageHead(title,desc,actions=''){return `<header class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</header>`}
  const missionDays=[
    {iso:'2026-11-23',day:'23',month:'NOV',title:'Départ et mise en route',text:'Vérifier les accès, les sauvegardes hors ligne et le cadre de confidentialité.'},
    {iso:'2026-11-24',day:'24',month:'NOV',title:'Repérage Guangzhou',text:'Organiser les zones de visite et confirmer les priorités de la mission.'},
    {iso:'2026-11-25',day:'25',month:'NOV',title:'Sourcing · vague 1',text:'Comparer les premières catégories sans publier les noms ni conditions commerciales.'},
    {iso:'2026-11-26',day:'26',month:'NOV',title:'Sourcing · vague 2',text:'Documenter les écarts de qualité, de conformité et de délai.'},
    {iso:'2026-11-27',day:'27',month:'NOV',title:'Échantillons et preuves',text:'Identifier les éléments à vérifier avant toute décision d’achat.'},
    {iso:'2026-11-28',day:'28',month:'NOV',title:'Comparaison intermédiaire',text:'Rapprocher besoins, quantités et contraintes logistiques.'},
    {iso:'2026-11-29',day:'29',month:'NOV',title:'Revue hebdomadaire',text:'Nettoyer les notes, sauvegarder et classer les pistes à poursuivre.'},
    {iso:'2026-11-30',day:'30',month:'NOV',title:'Sélection courte',text:'Réduire le catalogue aux options réellement comparables.'},
    {iso:'2026-12-01',day:'01',month:'DÉC',title:'Vérifications fournisseurs',text:'Contrôler les preuves et conditions dans l’espace collaboratif privé.'},
    {iso:'2026-12-02',day:'02',month:'DÉC',title:'Coûts complets',text:'Consolider transport, taxes, frais et risques dans les outils de pilotage.'},
    {iso:'2026-12-03',day:'03',month:'DÉC',title:'Décisions provisoires',text:'Classer les achats retenus, à confirmer ou à écarter.'},
    {iso:'2026-12-04',day:'04',month:'DÉC',title:'Propositions et validation',text:'Préparer une synthèse sans surestimer la demande ni les marges.'},
    {iso:'2026-12-05',day:'05',month:'DÉC',title:'Clôture opérationnelle',text:'Vérifier les exports, les preuves et les prochaines actions.'},
    {iso:'2026-12-06',day:'06',month:'DÉC',title:'Retour et transmission',text:'Archiver les données locales et préparer les relances du 7 au 15 décembre.'}
  ];
  const pilotageHelp={vision:'Objectifs et critères de réussite',finance:'Budget, marge et remboursement',france:'Pistes, coûts et statuts',sal:'Hypothèses touristiques',carnet:'Notes fournisseur locales',contacts:'Rendez-vous locaux',roadmap:'Préparation et suivi',journal:'Journal quotidien',presentation:'Vue sobre et imprimable'};
  function field(label,name,type='text',value='',wide=false,opts=''){const cls=wide?'field wide':'field';if(type==='textarea')return `<div class="${cls}"><label for="${name}">${label}</label><textarea id="${name}" name="${name}">${esc(value)}</textarea></div>`;if(type==='select')return `<div class="${cls}"><label for="${name}">${label}</label><select id="${name}" name="${name}">${opts}</select></div>`;return `<div class="${cls}"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}"></div>`}
  function navLinks(list){return list.map(([id,label])=>`<a class="nav-link ${id===current?'active':''}" href="#${id}" data-route="${id}"${id===current?' aria-current="page"':''}><span class="nav-icon">${icons[id]}</span><span>${label}</span></a>`).join('')}
  function renderNav(){document.querySelector('#nav').innerHTML=`<div class="nav-section primary-nav">${navLinks(primaryRoutes)}</div><div class="nav-label">Outils existants</div><div class="nav-section secondary-nav">${navLinks(secondaryRoutes)}</div>`}
  function render(){if(!routes.some(r=>r[0]===current))current='mission';renderNav();document.querySelector('#page').innerHTML=`<section class="page active" data-page="${current}">${pages[current]()}</section>`;bindPage();document.querySelector('#main').focus({preventScroll:true})}
  const pages = {
    mission:()=>{
      const filled=state.catalogue.filter(x=>x.product.trim()).length;return `<section class="business-hero"><img class="business-hero-image" src="assets/mission-route-decorative.jpg" alt=""><div class="business-hero-shade"></div><div class="business-hero-content"><p class="route-stamp">Guangzhou · France · Sal</p><h1>BUSINESS<br>CHINE</h1><p class="objective">Un portail mobile pour préparer, suivre et présenter la mission commerciale, sans publier les données de négociation.</p><div class="mission-window"><span>Départ</span><strong>23 NOV</strong><i></i><span>Retour</span><strong>06 DÉC</strong><small>2026 · 14 jours</small></div><div class="hero-actions"><button class="primary" data-go="timeline">Voir les 14 jours</button><a class="secondary button-link" href="${TENCENT_URL}" target="_blank" rel="noreferrer">Ouvrir Tencent Docs</a></div></div><span class="decorative-label">Visuel décoratif · aucune valeur de preuve</span></section>
      <section class="public-notice"><div class="notice-mark" aria-hidden="true">PUBLIC</div><div><h2>Deux espaces, deux usages</h2><p>Ce site reste public et ne contient que la structure de mission. Les prix négociés, fournisseurs, contacts et rendez-vous restent dans Tencent Docs, sous les accès gérés par Tencent.</p></div><span class="separation-line">Aucune synchronisation automatique</span></section>
      <section class="command-strip"><button data-go="catalogue"><strong>${filled}/25</strong><span>postes renseignés sur cet appareil</span></button><button data-go="timeline"><strong>14</strong><span>jours dans la timeline</span></button><button data-go="equipe"><strong>2</strong><span>rôles nommés</span></button><button data-go="pilotage"><strong>${state.metrics.progress}%</strong><span>progression locale existante</span></button></section>
      <section class="home-grid"><div class="home-statement"><h2>Le site donne le cap.<br>Le tableur garde le détail.</h2><p>La V2 rend l’itinéraire, les 25 achats et les responsabilités lisibles sur mobile. Les modules financiers, contacts, journal et calculs de la V1 restent accessibles dans Pilotage.</p></div><div class="home-next"><h2>À faire maintenant</h2><ol><li>Qualifier les 25 postes sans information confidentielle.</li><li>Compléter les rendez-vous dans Tencent Docs.</li><li>Exporter une sauvegarde locale avant chaque étape importante.</li></ol><button class="secondary" data-go="catalogue">Commencer le catalogue</button></div></section>`},
    timeline:()=>`${pageHead('23 NOV — 06 DÉC','Trame publique de mission. Les rendez-vous, adresses et noms de fournisseurs restent dans Tencent Docs.')}
      <div class="timeline-ledger">${missionDays.map((d,i)=>`<article class="day-row"><time datetime="${d.iso}"><strong>${d.day}</strong><span>${d.month}</span></time><div class="day-index">${String(i+1).padStart(2,'0')}</div><div><h2>${d.title}</h2><p>${d.text}</p></div><span class="day-state">Trame à compléter</span></article>`).join('')}</div><div class="timeline-footer"><p>Cette timeline n’affirme aucun rendez-vous confirmé. Utiliser Tencent pour le planning collaboratif détaillé.</p><a class="secondary button-link" href="${TENCENT_URL}" target="_blank" rel="noreferrer">Ouvrir le planning Tencent</a></div>`,
    catalogue:()=>{const filled=state.catalogue.filter(x=>x.product.trim()).length;return `${pageHead('Catalogue · 25 achats','25 emplacements locaux pour qualifier les achats. Aucun contenu de ce catalogue n’est envoyé au serveur.',`<button class="secondary" data-export="catalogue">Exporter CSV</button>`)}
      <div class="catalogue-summary"><div><strong>${filled}</strong><span>renseignés</span></div><div><strong>${25-filled}</strong><span>à qualifier</span></div><p>Éviter les noms de fournisseurs, coordonnées, prix négociés et conditions confidentielles. Ces informations appartiennent au document Tencent.</p></div>
      <form id="catalogueForm" class="catalogue-editor"><label>Poste<select name="slot">${state.catalogue.map(x=>`<option value="${x.slot}">Achat ${String(x.slot).padStart(2,'0')}</option>`).join('')}</select></label><label>Désignation locale<input name="product" maxlength="80" placeholder="Ex. accessoire à qualifier"></label><label>Catégorie<input name="category" maxlength="50" placeholder="Catégorie générique"></label><label>Quantité<input name="quantity" type="number" min="1" max="999" value="1"></label><label>Statut<select name="status"><option>À qualifier</option><option>À comparer</option><option>À valider</option><option>Retenu</option><option>Écarté</option></select></label><label class="wide">Note publique sûre<textarea name="note" maxlength="180" placeholder="Critère ou prochaine action, sans information confidentielle"></textarea></label><button class="primary" type="submit">Enregistrer sur cet appareil</button></form>
      <div class="purchase-ledger">${state.catalogue.map(p=>`<button class="purchase-row" type="button" data-edit-purchase="${p.slot}"><span class="purchase-number">${String(p.slot).padStart(2,'0')}</span><span><strong>${esc(p.product||'Poste à qualifier')}</strong><small>${esc(p.category||'Catégorie non définie')} · Qté ${esc(p.quantity)}</small></span>${statusTag(p.status,p.status==='Retenu'?'good':p.status==='Écarté'?'risk':'info')}</button>`).join('')}</div>`},
    equipe:()=>`${pageHead('Équipe et responsabilités','Une lecture publique des rôles. Les coordonnées personnelles ne sont pas publiées.')}
      <div class="team-board"><article><span class="team-code">ET</span><div><h2>Edmond Tavares</h2><p>Pilotage de la mission, qualification des achats, suivi du budget et décisions.</p></div><strong>Mission</strong></article><article><span class="team-code">VA</span><div><h2>Valencia</h2><p>Contribution au document collaboratif distinct et suivi des informations qui ne doivent pas apparaître sur le site public.</p></div><strong>Tencent</strong></article><article class="unassigned"><span class="team-code">+</span><div><h2>Validation des achats</h2><p>Rôle à confirmer pour la relecture des 25 postes et la décision finale.</p></div><strong>À attribuer</strong></article></div>
      <div class="responsibility-map"><h2>Séparation des responsabilités</h2><dl><div><dt>Site public</dt><dd>Cap, timeline, structure des 25 achats, équipe et accès au document collaboratif.</dd></div><div><dt>Tencent Docs</dt><dd>Rendez-vous, contacts, fournisseurs, prix, validations et détails de négociation.</dd></div><div><dt>Stockage local</dt><dd>Les données saisies dans les outils Pilotage restent dans le navigateur de l’appareil.</dd></div></dl></div>`,
    pilotage:()=>`${pageHead('Pilotage existant','Toutes les fonctions de la V1 sont conservées. Elles utilisent le stockage local de ce navigateur.')}
      <div class="pilotage-map">${secondaryRoutes.map(([id,label])=>`<button data-go="${id}"><span class="nav-icon">${icons[id]}</span><strong>${label}</strong><small>${pilotageHelp[id]}</small></button>`).join('')}</div><div class="privacy-panel"><h2>Avant de saisir</h2><p>Le site est public, mais les données opérationnelles sont stockées localement dans votre navigateur. N’y saisissez pas de mots de passe, données bancaires, pièces d’identité ou informations confidentielles de tiers. Exportez régulièrement une sauvegarde JSON.</p></div>`,
    vision:()=>`${pageHead('Vision et objectifs','Une mission commerciale en trois axes, avec des résultats observables plutôt que des promesses.')}
      <div class="axis-list"><div class="axis"><div class="axis-symbol">FR</div><div><h3>Revente sur commande en France</h3><p>Valider la demande avant l’achat, calculer le coût complet et sécuriser la conformité.</p></div></div><div class="axis"><div class="axis-symbol">CN</div><div><h3>Sourcing Chine–France–Cap-Vert</h3><p>Rechercher, comparer et négocier pour des clients contre une commission transparente.</p></div></div><div class="axis"><div class="axis-symbol">SAL</div><div><h3>Solutions touristiques à Sal</h3><p>Partir d’un besoin local vérifié, puis tester un modèle léger et mesurable.</p></div></div></div>
      <h2 class="section-title">Résultats attendus</h2><div class="split"><div class="panel"><ul><li>Commandes concrètes et documentées</li><li>Fournisseurs vérifiés selon une grille commune</li><li>Premières recettes encaissées</li><li>Début du remboursement</li><li>Une opportunité testable à Sal</li></ul></div><div class="panel accent-panel"><h3>Critère de réussite</h3><p>Quitter Guangzhou avec moins d’hypothèses, des preuves traçables et une prochaine décision claire pour chaque piste.</p></div></div>`,
    finance:()=>{const f=state.finance, remaining=f.envelope-f.actualExpenses-f.productCost, gross=f.revenue-f.productCost, net=gross-f.actualExpenses, debt=Math.max(0,f.remainingDebt-f.repayment);return `${pageHead('Tableau financier','Tous les montants sont modifiables. Les résultats se recalculent automatiquement.',`<button class="secondary" data-export="finance">Exporter CSV</button>`)}
      <div class="finance-summary"><div class="finance-stat"><span>Argent restant</span><strong>${money(remaining)}</strong></div><div class="finance-stat"><span>Marge</span><strong>${money(gross)}</strong></div><div class="finance-stat"><span>Bénéfice net</span><strong>${money(net)}</strong></div></div>
      <div class="split" style="margin-top:18px"><form id="financeForm" class="panel editable-grid">${field('Enveloppe disponible (€)','envelope','number',f.envelope)}${field('Budget prévu du voyage (€)','travelBudget','number',f.travelBudget)}${field('Dépenses réelles (€)','actualExpenses','number',f.actualExpenses)}${field('Coût des produits (€)','productCost','number',f.productCost)}${field('Chiffre d’affaires (€)','revenue','number',f.revenue)}${field('Recettes encaissées (€)','received','number',f.received)}${field('Montant affecté au remboursement (€)','repayment','number',f.repayment)}${field('Solde à rembourser avant affectation (€)','remainingDebt','number',f.remainingDebt)}<div class="form-actions"><button class="primary" type="submit">Enregistrer et recalculer</button></div></form><div class="panel dark-panel"><h2>Lecture rapide</h2><p>Budget prévu : <strong>${money(f.travelBudget)}</strong></p><p>Dépenses + produits : <strong>${money(f.actualExpenses+f.productCost)}</strong></p><p>Solde restant à rembourser : <strong>${money(debt)}</strong></p><p class="hint">Le bénéfice net affiché est la marge après les dépenses réelles du voyage.</p></div></div>
      <h2 class="section-title">Les mots du tableau</h2><div class="definitions"><div class="definition"><strong>Chiffre d’affaires</strong><p>Total payé par les clients.</p></div><div class="definition"><strong>Marge</strong><p>Différence entre le prix de vente et le coût du produit.</p></div><div class="definition"><strong>Bénéfice net</strong><p>Marge restante après tous les frais.</p></div></div>`},
    france:()=>{const statuses=['tous','idée','demande à tester','demande confirmée','prix à vérifier','fournisseur identifié','commande reçue','acheté','vendu','abandonné'];return `${pageHead('Opportunités France','Chaque piste combine demande, coût complet, marge, risque et prochaine action.',`<button class="primary" data-open-form="franceForm">Ajouter une opportunité</button><button class="secondary" data-export="france">Exporter CSV</button>`)}
      <div class="panel" id="franceForm" hidden><form id="opportunityForm" class="editable-grid">${field('Produit','product')}${field('Catégorie','category')}${field('Image (URL facultative)','image','url')}${field('Client cible','target')}${field('Personnes intéressées','interest','number',0)}${field('Prix fournisseur (RMB)','rmb','number',0)}${field('Transport (€)','shipping','number',0)}${field('Taxes (€)','taxes','number',0)}${field('Frais de paiement (€)','fees','number',0)}${field('Prix de vente (€)','sale','number',0)}${field('Commission (€)','commission','number',0)}${field('Risque','risk','select','',false,['Faible','Moyen','Élevé'].map(x=>`<option>${x}</option>`).join(''))}${field('Statut','status','select','',false,statuses.slice(1).map(x=>`<option>${x}</option>`).join(''))}${field('Prochaine action','action','textarea','',true)}<div class="form-actions"><button class="primary" type="submit">Ajouter</button><button class="danger" type="button" data-close-form="franceForm">Annuler</button></div></form></div>
      <div class="table-tools"><input id="franceSearch" type="search" placeholder="Rechercher un produit"><select id="franceStatus">${statuses.map(s=>`<option value="${s}">${s==='tous'?'Tous les statuts':s}</option>`).join('')}</select><label>Taux : <input id="exchangeRate" type="number" step="0.01" value="${state.meta.exchangeRate}" style="width:90px"> RMB / €</label></div><div id="franceTable">${franceTable(state.france)}</div>`},
    sal:()=>`${pageHead('Opportunités Sal','Des hypothèses à valider avec des partenaires locaux, des coûts réels et des règles claires.')}
      <div class="sal-grid">${state.sal.map(o=>`<article class="sal-card ${o.priority?'priority':''}"><div>${statusTag(o.decision,o.priority?'good':'example')}<h3>${esc(o.name)}</h3></div><dl><div><dt>Besoin identifié</dt><dd>${esc(o.need)}</dd></div><div><dt>Partenaire potentiel</dt><dd>${esc(o.partner)}</dd></div><div><dt>Investissement</dt><dd>${money(o.investment)}</dd></div><div><dt>Transport</dt><dd>${money(o.transport)}</dd></div><div><dt>Entretien + assurance</dt><dd>${money(o.maintenance+o.insurance)}</dd></div><div><dt>Revenu potentiel</dt><dd>${money(o.revenue)} · estimation</dd></div><div><dt>Amortissement</dt><dd>${esc(o.payback)}</dd></div><div><dt>Risques</dt><dd>${esc(o.risks)}</dd></div></dl><div class="card-actions"><span class="hint">${esc(o.action)}</span><button class="secondary" data-edit-sal="${o.id}">Modifier</button></div></article>`).join('')}</div>`,
    carnet:()=>`${pageHead('Carnet de mission à Guangzhou','Consigner un rendez-vous fournisseur depuis le téléphone. Ne pas saisir de données sensibles.',`<button class="secondary" data-export="carnet">Exporter CSV</button>`)}
      <div class="split"><form id="carnetForm" class="panel editable-grid">${field('Date','date','date',today)}${field('Lieu','place')}${field('Marché ou fournisseur','supplier')}${field('Catégorie','category')}${field('Photos','photos','file')}${field('Coordonnées non sensibles','contact')}${field('Prix (RMB)','rmb','number',0)}${field('Quantité minimale','moq','number',1)}${field('Échantillon possible','sample','select','',false,'<option>À vérifier</option><option>Oui</option><option>Non</option>')}${field('Conditions de paiement','payment')}${field('Délai','lead')}${field('Qualité','quality')}${field('Garantie','warranty')}${field('Conformité','compliance')}${field('Statut','status','select','',false,'<option>à vérifier</option><option>contacté</option><option>échantillon demandé</option><option>vérifié</option><option>écarté</option>')}${field('Prochaine action','action','textarea','',true)}<div class="form-actions"><button class="primary" type="submit">Ajouter au carnet</button></div></form><div><div class="panel dark-panel"><h2>Grille de vérification</h2><ul><li>Identité légale et coordonnées vérifiables</li><li>Échantillon comparé à une spécification</li><li>Conformité UE à confirmer par document</li><li>Conditions écrites, garantie et délai</li><li>Aucun paiement important sans contrôle adapté</li></ul></div><div id="carnetList" class="journal-list" style="margin-top:14px">${recordsList(state.carnet,'carnet')}</div></div></div>`,
    contacts:()=>`${pageHead('Contacts et rendez-vous','Centraliser les relations sans stocker de données confidentielles.',`<button class="secondary" data-export="contacts">Exporter CSV</button>`)}<div class="split"><form id="contactForm" class="panel editable-grid">${field('Nom','name')}${field('Entreprise','company')}${field('Pays','country')}${field('Secteur','sector')}${field('Type de contact','type','select','',false,['acheteur français','fournisseur chinois','hôtel à Sal','agence de voyage','loueur automobile','guide','partenaire local','investisseur','contact à relancer'].map(x=>`<option>${x}</option>`).join(''))}${field('Besoin','need')}${field('Date du rendez-vous','meeting','datetime-local')}${field('Prochaine action','action')}${field('Potentiel','potential','select','',false,'<option>À évaluer</option><option>Faible</option><option>Moyen</option><option>Fort</option>')}${field('Statut','status','select','',false,'<option>à contacter</option><option>rendez-vous prévu</option><option>contacté</option><option>à relancer</option><option>qualifié</option>')}<div class="form-actions"><button class="primary" type="submit">Ajouter le contact</button></div></form><div id="contactList">${contactsTable()}</div></div>`,
    roadmap:()=>`${pageHead('Roadmap','Une frise de préparation, mission, relance et répétition commerciale.')}<div class="timeline">${[
      ['19–22 novembre','Préparer et tester la demande','Lister les besoins, sonder les acheteurs, fixer des plafonds de coût.','Demandes qualifiées avant départ','Prospects, budgets, intentions'],['23 novembre','Départ','Vérifier les outils hors ligne, exports et documents non sensibles.','Mission prête à opérer','Checklist de départ'],['24 novembre–6 décembre','Mission à Guangzhou','Rencontrer, comparer, documenter, demander des échantillons.','Fournisseurs et offres comparables','Rendez-vous, offres, vérifications'],['7–15 décembre','Relances et devis','Confirmer conditions, transport, taxes, conformité et délais.','Devis complets envoyés','Taux de réponse, devis'],['Jours 30–60','Premières ventes et commissions','Exécuter les commandes validées et suivre l’encaissement.','Premières recettes','CA, marge, remboursement'],['Jours 60–90','Répétition et test à Sal','Répéter les ventes rentables et valider un test local léger.','Boucle commerciale répétable','Récurrence, amortissement']
      ].map((x,i)=>`<div class="timeline-item"><div class="timeline-dot"></div><div class="timeline-date">${x[0]}</div><div class="timeline-body"><h3>${x[1]}</h3><div class="timeline-meta"><div><strong>Tâches</strong><p>${x[2]}</p></div><div><strong>Résultat attendu</strong><p>${x[3]}</p></div><div><strong>Indicateurs</strong><p>${x[4]}</p></div></div></div></div>`).join('')}</div>`,
    journal:()=>`${pageHead('Journal de mission','Transformer chaque journée en apprentissage, décision et prochaine action.',`<button class="secondary" data-export="journal">Exporter CSV</button>`)}<div class="split"><form id="journalForm" class="panel editable-grid">${field('Date','date','date',today)}${field('Ce que j’ai fait','done','textarea','',true)}${field('Personnes rencontrées','people','textarea','',true)}${field('Ce que j’ai appris','learned','textarea','',true)}${field('Prix obtenus','prices','textarea','',true)}${field('Opportunités','opportunities','textarea','',true)}${field('Problèmes','problems','textarea','',true)}${field('Décisions','decisions','textarea','',true)}${field('Prochaine action','action','textarea','',true)}<div class="form-actions"><button class="primary" type="submit">Enregistrer la journée</button></div></form><div class="journal-list">${recordsList(state.journal,'journal')}</div></div>`,
    presentation:()=>`${pageHead('Présentation pour mon oncle','Vue synthétique, sans notes personnelles ni données non présentables.',`<button class="primary" id="enterPresentation">Lancer la présentation</button>`)}
      <div class="presentation-hero"><h1>Une mission, trois marchés.</h1><p>Structurer Guangzhou comme le point de départ d’une boucle commerciale : demandes françaises, fournisseurs qualifiés et une opportunité touristique testable à Sal.</p><div class="hero-meta"><span><strong>${money(state.finance.envelope)}</strong><br>enveloppe locale</span><span><strong>14 jours</strong><br>pour qualifier et comparer</span><span><strong>90 jours</strong><br>pour tester la répétition</span></div></div>
      <div class="decision-grid"><div class="panel"><h2>Décisions recommandées</h2><div class="decision-list"><div class="decision"><span class="decision-mark">✓</span><div><strong>Acheter après validation</strong><br><span class="hint">Prioriser les commandes ou demandes confirmées.</span></div></div><div class="decision"><span class="decision-mark">✓</span><div><strong>Comparer le coût complet</strong><br><span class="hint">Produit, transport, taxes, paiement et conformité.</span></div></div><div class="decision"><span class="decision-mark">✓</span><div><strong>Tester Sal en format léger</strong><br><span class="hint">Les vélos électriques restent une hypothèse prioritaire à valider.</span></div></div></div></div><div class="panel warning-panel"><h2>Risques à maîtriser</h2><ul class="risk-list"><li>Demande surestimée</li><li>Conformité et garantie insuffisantes</li><li>Coûts de transport et taxes incomplets</li><li>Fournisseur non vérifié</li><li>Investissement à Sal avant preuve locale</li></ul></div></div>
      <h2 class="section-title">Budget et résultats attendus</h2><div class="finance-summary"><div class="finance-stat"><span>Enveloppe</span><strong>${money(state.finance.envelope)}</strong></div><div class="finance-stat"><span>Dépenses réelles</span><strong>${money(state.finance.actualExpenses)}</strong></div><div class="finance-stat"><span>Recettes encaissées</span><strong>${money(state.finance.received)}</strong></div></div><div class="panel" style="margin-top:18px"><h2>Prochaines étapes</h2><p>Tester la demande en France, fixer les critères fournisseur, préparer les rendez-vous à Guangzhou, puis conduire les relances du 7 au 15 décembre. Les résultats seront mesurés par les demandes confirmées, les fournisseurs vérifiés, la marge nette et les recettes encaissées.</p></div>`
  };
  function franceTable(rows){if(!rows.length)return '<div class="empty">Aucune opportunité ne correspond aux filtres.</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Produit</th><th>Image</th><th>Client cible</th><th>Intérêt</th><th>Prix fournisseur</th><th>Coût complet</th><th>Prix de vente</th><th>Marge estimée</th><th>Commission</th><th>Risque</th><th>Statut</th><th>Prochaine action</th><th>Action</th></tr></thead><tbody>${rows.map(o=>`<tr><td><strong>${esc(o.product)}</strong><br>${statusTag('exemple provisoire','example')}<br><span class="hint">${esc(o.category)}</span></td><td>${o.image?`<img src="${esc(o.image)}" alt="Aperçu de ${esc(o.product)}" style="width:56px;height:56px;object-fit:cover;border-radius:9px">`:'<span class="hint">À ajouter</span>'}</td><td>${esc(o.target)}</td><td>${o.interest}</td><td class="money">${rmbDisplay(o.rmb)}</td><td class="money">${money(cost(o))}</td><td class="money">${money(o.sale)}</td><td class="money"><strong>${money(margin(o))}</strong></td><td class="money">${money(o.commission)}</td><td>${statusTag(o.risk,o.risk==='Élevé'?'risk':'')}</td><td>${statusTag(o.status,'info')}</td><td>${esc(o.action)}</td><td data-label="Action"><button class="danger" data-delete-france="${o.id}">Supprimer</button></td></tr>`).join('')}</tbody></table></div>`}
  function recordsList(rows,type){if(!rows.length)return '<div class="empty">Aucune entrée pour le moment.</div>';return rows.slice().reverse().map(r=>`<article class="journal-entry"><header><h3>${esc(r.date||r.supplier||'Entrée')}</h3>${statusTag(type==='carnet'?(r.status||'à vérifier'):'journal')}</header><p>${esc(type==='carnet'?`${r.supplier||'Fournisseur à nommer'} · ${r.place||'Lieu à préciser'} · ${r.rmb? rmbDisplay(r.rmb):'Prix à vérifier'}`:(r.done||'Journée sans résumé'))}</p><strong>Prochaine action :</strong> ${esc(r.action||'À définir')}${r.photo?`<div class="photo-preview"><img src="${r.photo}" alt="Photo ajoutée au carnet"></div>`:''}</article>`).join('')}
  function contactsTable(){if(!state.contacts.length)return '<div class="empty">Aucun contact. Ajoutez le premier rendez-vous.</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Nom</th><th>Entreprise</th><th>Pays</th><th>Type</th><th>Besoin</th><th>Rendez-vous</th><th>Potentiel</th><th>Statut</th><th>Prochaine action</th></tr></thead><tbody>${state.contacts.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.company)}</td><td>${esc(c.country)}</td><td>${esc(c.type)}</td><td>${esc(c.need)}</td><td>${esc(c.meeting)}</td><td>${statusTag(c.potential)}</td><td>${statusTag(c.status,'info')}</td><td>${esc(c.action)}</td></tr>`).join('')}</tbody></table></div>`}
  function formData(form){return Object.fromEntries(new FormData(form).entries())}
  function csv(rows){if(!rows.length)return '';const cols=[...new Set(rows.flatMap(Object.keys))].filter(x=>!['id','photo'].includes(x));const q=v=>`"${String(v??'').replaceAll('"','""')}"`;return [cols.map(q).join(';'),...rows.map(r=>cols.map(c=>q(r[c])).join(';'))].join('\n')}
  function download(name,data,type='application/json'){const blob=new Blob([data],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
  function exportCsv(kind){let rows=kind==='finance'?[state.finance]:state[kind]||[];download(`mission-chine-2026-${kind}.csv`,`\uFEFF${csv(rows)}`,'text/csv;charset=utf-8');toast('Export CSV créé')}
  function bindPage(){
    document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.go});
    document.querySelectorAll('[data-open-form]').forEach(b=>b.onclick=()=>document.querySelector(`#${b.dataset.openForm}`).hidden=false);
    document.querySelectorAll('[data-close-form]').forEach(b=>b.onclick=()=>document.querySelector(`#${b.dataset.closeForm}`).hidden=true);
    document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>exportCsv(b.dataset.export));
    const ff=document.querySelector('#financeForm');if(ff)ff.onsubmit=e=>{e.preventDefault();Object.entries(formData(ff)).forEach(([k,v])=>state.finance[k]=Number(v)||0);state.metrics.received=state.finance.received;save();render()};
    const of=document.querySelector('#opportunityForm');if(of)of.onsubmit=e=>{e.preventDefault();const d=formData(of);['interest','rmb','shipping','taxes','fees','sale','commission'].forEach(k=>d[k]=Number(d[k])||0);state.france.push({id:uid(),...d,example:true});save();render()};
    document.querySelectorAll('[data-delete-france]').forEach(b=>b.onclick=()=>{state.france=state.france.filter(x=>x.id!==b.dataset.deleteFrance);save();render()});
    const rate=document.querySelector('#exchangeRate');if(rate)rate.onchange=()=>{state.meta.exchangeRate=Math.max(.01,Number(rate.value)||7.31);save('Taux de change mis à jour');render()};
    const fs=document.querySelector('#franceSearch'),fst=document.querySelector('#franceStatus');if(fs&&fst){const filter=()=>{const q=fs.value.toLowerCase(),s=fst.value;const rows=state.france.filter(o=>(!q||JSON.stringify(o).toLowerCase().includes(q))&&(s==='tous'||o.status===s));document.querySelector('#franceTable').innerHTML=franceTable(rows);bindDeleteOnly()};fs.oninput=filter;fst.onchange=filter}
    const cf=document.querySelector('#carnetForm');if(cf)cf.onsubmit=async e=>{e.preventDefault();const d=formData(cf),file=cf.elements.photos.files[0];d.rmb=Number(d.rmb)||0;d.moq=Number(d.moq)||0;if(file){if(file.size>700000){toast('Photo trop lourde : maximum 700 Ko en V1');return}d.photo=await toDataUrl(file)}state.carnet.push({id:uid(),...d});save();render()};
    const contact=document.querySelector('#contactForm');if(contact)contact.onsubmit=e=>{e.preventDefault();state.contacts.push({id:uid(),...formData(contact)});save();render()};
    const journal=document.querySelector('#journalForm');if(journal)journal.onsubmit=e=>{e.preventDefault();state.journal.push({id:uid(),...formData(journal)});save();render()};
    const catalogue=document.querySelector('#catalogueForm');if(catalogue)catalogue.onsubmit=e=>{e.preventDefault();const d=formData(catalogue),item=state.catalogue.find(x=>x.slot===Number(d.slot));if(!item)return;Object.assign(item,{product:d.product.trim(),category:d.category.trim(),quantity:Math.max(1,Number(d.quantity)||1),status:d.status,note:d.note.trim()});save('Poste enregistré localement');render()};
    document.querySelectorAll('[data-edit-purchase]').forEach(b=>b.onclick=()=>{const item=state.catalogue.find(x=>x.slot===Number(b.dataset.editPurchase)),form=document.querySelector('#catalogueForm');if(!item||!form)return;form.elements.slot.value=item.slot;form.elements.product.value=item.product;form.elements.category.value=item.category;form.elements.quantity.value=item.quantity;form.elements.status.value=item.status;form.elements.note.value=item.note;form.scrollIntoView({behavior:'smooth',block:'start'});form.elements.product.focus()});
    document.querySelectorAll('[data-edit-sal]').forEach(b=>b.onclick=()=>editSal(b.dataset.editSal));
    const ep=document.querySelector('#enterPresentation');if(ep)ep.onclick=()=>setPresentation(true);
  }
  function bindDeleteOnly(){document.querySelectorAll('[data-delete-france]').forEach(b=>b.onclick=()=>{state.france=state.france.filter(x=>x.id!==b.dataset.deleteFrance);save();render()})}
  function toDataUrl(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
  function editSal(id){
    const o=state.sal.find(x=>x.id===id);if(!o)return;
    const ask=(label,value)=>prompt(label,String(value??''));
    const need=ask('Besoin identifié (indiquer “à vérifier” si non confirmé)',o.need);if(need===null)return;
    const partner=ask('Client ou partenaire potentiel',o.partner);if(partner===null)return;
    const investment=ask('Investissement estimé (€)',o.investment);if(investment===null)return;
    const transport=ask('Transport estimé (€)',o.transport);if(transport===null)return;
    const maintenance=ask('Entretien estimé (€)',o.maintenance);if(maintenance===null)return;
    const insurance=ask('Assurance estimée (€)',o.insurance);if(insurance===null)return;
    const revenue=ask('Revenu potentiel estimé (€)',o.revenue);if(revenue===null)return;
    const payback=ask('Durée estimée d’amortissement',o.payback);if(payback===null)return;
    const risks=ask('Risques',o.risks);if(risks===null)return;
    const action=ask('Prochaine action',o.action);if(action===null)return;
    const decision=ask('Décision / statut',o.decision);if(decision===null)return;
    Object.assign(o,{need,partner,investment:Number(investment)||0,transport:Number(transport)||0,maintenance:Number(maintenance)||0,insurance:Number(insurance)||0,revenue:Number(revenue)||0,payback,risks,action,decision});save();render()
  }
  function setPresentation(on){presentation=on;document.body.classList.toggle('presentation',on);const b=document.querySelector('#modeToggle');b.setAttribute('aria-pressed',String(on));b.querySelector('span:last-child').textContent=on?'Quitter la présentation':'Mode présentation';if(on){current='presentation';location.hash='presentation'}render()}
  document.querySelector('#modeToggle').onclick=()=>setPresentation(!presentation);
  document.querySelector('#printPresentation').onclick=()=>{if(current!=='presentation'){current='presentation';render()}setTimeout(()=>window.print(),80)};
  document.querySelector('#exportProject').onclick=()=>{const backup={...state,journey:JSON.parse(localStorage.getItem('businessChine.journey.v22')||'{}')};download(`mission-chine-2026-sauvegarde-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(backup,null,2))};
  document.querySelector('#globalSearch').oninput=e=>{const q=e.target.value.trim().toLowerCase();if(q.length<2)return;const route=routes.find(([id,label])=>label.toLowerCase().includes(q)||JSON.stringify(state[id]||'').toLowerCase().includes(q));if(route&&route[0]!==current){current=route[0];location.hash=current;render()}};
  addEventListener('hashchange',()=>{current=location.hash.slice(1)||'mission';if(presentation&&current!=='presentation')setPresentation(false);else render();scrollTo(0,0)});
  installMissionDashboard({pages,state,missionDays,primaryRoutes,secondaryRoutes,TENCENT_URL,esc,icons,render});
  render();
})();
